//! The message material schema (node model) — the cross-media
//! single source of truth: one schema, three projections (prost
//! binary on the official stdio path, pbjson JSON on the
//! third-party path, verbatim pbjson projection inside transcript
//! rows). Deliberately stdio-free: link contracts live in
//! `zconned-types`.

// Generated by [`prost-build`]
include!(concat!(env!("OUT_DIR"), "/zconn.zconned.material.rs"));
// Generated by [`pbjson-build`]
include!(concat!(env!("OUT_DIR"), "/zconn.zconned.material.serde.rs"));

#[cfg(test)]
mod tests {
    use super::*;
    use pretty_assertions::assert_eq;
    use prost::Message as _;

    fn sample_msg() -> Msg {
        Msg {
            ver_major: 1,
            ver_minor: 0,
            body: Some(Node {
                meta: Some(Meta {
                    prev: vec![Ref {
                        ver_major: 1,
                        ver_minor: 2,
                        algo: "sha3-256".to_owned(),
                        digest: vec![0xab; 32],
                    }],
                }),
                kind: "text/plain".to_owned(),
                data: b"hello".to_vec(),
            }),
        }
    }

    #[test]
    fn ver_minor_zero_is_omitted_on_the_wire() {
        let mut msg = sample_msg();
        let with_zero = msg.encode_to_vec();
        msg.ver_minor = 1;
        let with_one = msg.encode_to_vec();
        // Field 2 (tag + varint) appears only when non-zero.
        assert_eq!(with_one.len(), with_zero.len() + 2);
    }

    #[test]
    fn material_roundtrips_through_transport_bytes() {
        let msg = sample_msg();
        let bytes = msg.encode_to_vec();
        assert_eq!(Msg::decode(bytes.as_slice()).unwrap(), msg);
    }

    #[test]
    fn canonical_profile_encoding_is_byte_exact() {
        // Pins the canonical profile: proto3, implicit presence,
        // field-number order, prost emission (protocol.md).
        let msg = sample_msg();
        let mut expected = vec![
            0x08, 0x01, // field 1: ver_major = 1
            0x1A, 0x47, // field 3: body, len 71
            0x0A, 0x32, //   field 1: meta, len 50
            0x0A, 0x30, //     field 1: prev[0], len 48
            0x08, 0x01, //       field 1: ver_major = 1
            0x10, 0x02, //       field 2: ver_minor = 2
            0x1A, 0x08, //       field 3: algo
        ];
        expected.extend_from_slice(b"sha3-256");
        expected.extend_from_slice(&[0x22, 0x20]); // field 4: digest, 32 B
        expected.extend_from_slice(&[0xab_u8; 32]);
        expected.extend_from_slice(&[
            0x12, 0x0A, //   field 2: kind
        ]);
        expected.extend_from_slice(b"text/plain");
        expected.extend_from_slice(&[
            0x1A, 0x05, //   field 3: data
        ]);
        expected.extend_from_slice(b"hello");
        assert_eq!(msg.encode_to_vec(), expected);
    }

    #[test]
    fn json_projection_is_the_verbatim_pbjson_shape() {
        let json = serde_json::to_string(&sample_msg()).unwrap();
        assert!(json.contains(r#""verMajor":1"#));
        assert!(json.contains(r#""kind":"text/plain""#));
        assert!(json.contains(r#""prev":[{"verMajor":1,"verMinor":2"#));
        assert!(json.contains(r#""algo":"sha3-256""#));
    }
}
